-- ASMAS verified handoff stored procedure; requires existing core schema.
CREATE OR REPLACE FUNCTION asmas.simple_finish(p_id uuid, p_token uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ declare t asmas.tasks%rowtype; nxt text; evt jsonb; rid uuid; n integer; handoff jsonb; next_payload jsonb; begin select * into t from asmas.tasks where id=p_id and status='LEASED' and lease_token=p_token and lease_until>now() for update; if not found then return false;end if; if p_result->>'model' is distinct from 'gemini-3.5-flash-lite' or p_result->>'agent' is distinct from t.agent or jsonb_typeof(p_result->'text') is distinct from 'string' or coalesce(length(btrim(p_result->>'text')),0)=0 or p_result->>'provider_verified' is distinct from 'true' then raise exception 'INVALID_MODEL_RESULT';end if; rid:=(t.payload->>'run_id')::uuid; update asmas.tasks set status='SUCCEEDED',lease_until=null,result=p_result where id=p_id; insert into asmas.activities(task_id,case_id,agent,action,result,synthetic) values(p_id,t.case_id,t.agent,t.action,'SUCCEEDED',true); nxt:=case when t.payload->>'director_mode'='true' then case t.agent when 'A3' then 'A4' end else case t.agent when 'A5' then 'A1' when 'A1' then 'A2' when 'A2' then 'A3' when 'A3' then 'A4' end end; if nxt is not null then handoff:=jsonb_build_object('schema_version','asmas.handoff.v1','run_id',rid,'source_task_id',t.id,'source_agent',t.agent,'destination_agent',nxt,'execution_mode','SYNTHETIC_ANALYSIS','is_synthetic',true,'commercial_flow_certified',false,'output',p_result);
next_payload:=t.payload||jsonb_build_object('previous_agent',t.agent,'previous_output',p_result->>'text','handoff',handoff);
evt:=jsonb_build_object('handoff',handoff,'run_id',rid,'source_agent',t.agent,'destination_agent',nxt,'is_synthetic',true); insert into asmas.outbox(topic,payload,published_at) values('asmas:db_task_queue',evt,now()); insert into asmas.messages(correlation_id,task_id,from_agent,to_agent,status,payload) values(rid::text,p_id,t.agent,nxt,'DELIVERED_TO_DB_QUEUE',evt); insert into asmas.tasks(case_id,agent,action,idempotency_key,payload) values(t.case_id,nxt,t.action,rid::text||':'||nxt,next_payload) on conflict(idempotency_key) do nothing; else select count(distinct agent) into n from asmas.tasks where payload->>'run_id'=rid::text and status='SUCCEEDED' and result->>'provider_verified'='true' and result->>'model'='gemini-3.5-flash-lite'; if n=5 then update asmas.synthetic_runs set status='COMPLETED',finished_at=now(), result=jsonb_build_object('agents_completed',n,'model','gemini-3.5-flash-lite','is_synthetic',true, 'commercial_flow_certified',false,'emails_sent',0,'payments',0) where run_id=rid;end if; end if; return true; end$function$
;
